-- 0064_mnemo_decision_confidence
--
-- Add the `confidence` column to `mnemo_decision` to match the
-- declared schema (`packages/core/src/db/schema/decision.ts`). The
-- TypeScript schema has carried `confidence: real("confidence")` since
-- the v1.6 LLM-judge integration, but no migration ever created the
-- column on disk — so every SELECT generated by Drizzle from the
-- column list (e.g. `buildGraphQuery` in `src/graph/query.ts`) crashed
-- with `UndefinedColumn: column mnemo_decision.confidence does not
-- exist` on any DB that started from migration 0018 and never had
-- the column hand-added.
--
-- The column is NULLABLE because most existing decisions weren't
-- self-rated by an LLM judge; we set NULL for everything older and let
-- new rows populate it organically.

ALTER TABLE mnemo_decision ADD COLUMN IF NOT EXISTS confidence real;
